head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > E > onscrollend]<br/>GridView 컴포넌트에서 세로 스크롤이 최하단에 닿을때마다 발생합니다.",
    "validation" : [
        "세로 스크롤이 최하단에 닿을때마다 onscrollend 이벤트가 발생해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정
    let properties = {
        dataList: "data:dlt_bind",
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onscrollend"]);

    // dataList 생성 (10행)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind', '', 10);

    // target 생성
    await $c.gcm.createBasicGridView(cList, eList);

    // 세로 스크롤 생성을 위해 height 변경
    target1.setStyle("height", "220px");
}



scwin.btn_scrollTop_onclick = function () {
    target1.setScrollTop(0);
}



scwin.btn_scrollMiddle_onclick = function () {
    let scrollArea = document.querySelector("div[id*='target1_scrollY']");
    if (scrollArea) {
        let maxScroll = scrollArea.scrollHeight - scrollArea.clientHeight;
        let middle = Math.round(maxScroll / 2);
        target1.setScrollTop(middle);
    }
}



scwin.btn_scrollBottom_onclick = function () {
    let scrollArea = document.querySelector("div[id*='target1_scrollY']");
    if (scrollArea) {
        let maxScroll = scrollArea.scrollHeight - scrollArea.clientHeight;
        target1.setScrollTop(maxScroll);
    }
}



scwin.target1_onscrollend = function () {
    wf_body_bottom.getObj("scwin").setReturnValue("=====target1_onscrollend=====");
}
